import sys
import math

def bin_pow(base, exp, p):
    res = 1
    cur = base
    while exp > 0:
        if exp & 1:
            res = res * cur % p
        cur = cur * cur % p
        exp >>= 1
    return res

def get_lower(x):
    res = 1
    while res < x:
        res <<= 1
    return res

def FWT(arr, length, inv=False):
    temp = arr[:]
    step = 1
    while step < length:
        for j in range(0, length, step << 1):
            for k in range(j, j + step):
                val = temp[k]
                if inv:
                    temp[k + step] -= val
                else:
                    temp[k + step] += val
        step <<= 1
    for i in range(length):
        arr[i] = temp[i] % p

def main():
    input = sys.stdin.read().strip().split()
    n, k, p = map(int, input[:3])
    total_pow = p * p

    if n & 1:
        print(bin_pow(k, n, p))
        return

    maxn = get_lower(n + 1) - 1
    popcount_arr = [bin(i).count('1') for i in range(maxn + 1)]
    fact_arr = [1] * (maxn + 1)
    inv_fact_arr = [1] * (maxn + 1)
    f_vals = [0] * (maxn + 1)
    tmp2_arr = [[0] * (maxn + 1) for _ in range(20)]
    tmp1_arr = [[0] * (maxn + 1) for _ in range(20)]
    tmp3_arr = [[0] * (maxn + 1) for _ in range(20)]
    trans_arr = [[0] * (maxn + 1) for _ in range(20)]
    total_pow = p * p

    # Prepare factorials and inverse factorials
    for i in range(1, maxn + 1):
        fact_arr[i] = fact_arr[i - 1] * i % p
    inv_fact_arr[maxn] = bin_pow(fact_arr[maxn], p - 2, p)
    for i in range(maxn - 1, -1, -1):
        inv_fact_arr[i] = inv_fact_arr[i + 1] * (i + 1) % p

    def mod_adjust(x):
        if x >= total_pow:
            x -= total_pow
        return x

    # Initialize tmp2_arr with inverse factorials
    for i in range(maxn + 1):
        tmp2_arr[popcount_arr[i]][i] = inv_fact_arr[i]

    # Perform initial FWT on tmp2_arr
    for i in range(20):
        FWT(tmp2_arr[i], maxn + 1)

    f_vals[0] = 1

    # Main computation
    res_k = k
    while res_k:
        if res_k & 1:
            # perform_multiplication
            for i in range(20):
                for s in range(maxn + 1):
                    tmp1_arr[i][s] = 0
            for i in range(maxn + 1):
                tmp1_arr[popcount_arr[i]][i] = 1  # f_vals[i] is 1 for initial, can be adjusted if needed

            for i in range(20):
                FWT(tmp1_arr[i], maxn + 1)

            for q in range(20):
                for l in range(20 - q):
                    for s in range(maxn + 1):
                        val = tmp1_arr[q][s] * tmp2_arr[l][s]
                        trans_arr[q + l][s] = (trans_arr[q + l][s] + val) % p

            for q in range(20):
                for s in range(maxn + 1):
                    tmp3_arr[q][s] = trans_arr[q][s] % p

            for i in range(20):
                FWT(tmp3_arr[i], maxn + 1, inv=True)

            for i in range(maxn + 1):
                f_vals[i] = tmp3_arr[popcount_arr[i]][i]

        res_k >>= 1
        if res_k:
            # perform_alt_multiplication
            for i in range(20):
                for s in range(maxn + 1):
                    trans_arr[i][s] = 0
            for q in range(20):
                for l in range(20 - q):
                    for s in range(maxn + 1):
                        val = tmp2_arr[q][s] * tmp2_arr[l][s]
                        trans_arr[q + l][s] = (trans_arr[q + l][s] + val) % p

            for i in range(20):
                for s in range(maxn + 1):
                    tmp3_arr[i][s] = trans_arr[i][s] % p

            for i in range(20):
                FWT(tmp3_arr[i], maxn + 1, inv=True)

            for i in range(20):
                for s in range(maxn + 1):
                    tmp2_arr[i][s] = 0

            for i in range(maxn + 1):
                tmp2_arr[popcount_arr[i]][i] = tmp3_arr[popcount_arr[i]][i]

            for i in range(20):
                FWT(tmp2_arr[i], maxn + 1)

    # Final output
    result = (bin_pow(k, n, p) - fact_arr[n] * f_vals[n] % p + p) % p
    print(result)

